sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    g_form.hideFieldMsg("initial_review.results_of_occurrence");
    g_form.showFieldMsg("initial_review.results_of_occurrence", getMessage('x_hccc_hoc_ohs.results_of_occurrence'));

}
